function acr_check($ok,$message){if(!$ok){throw new RuntimeException($message);}}
function acr_sql($sql){global$control;$r=$control->sql_query($sql);if($r===false){$error=$control->sql_error();throw new RuntimeException('Own recovery CLI fixture SQL failed: code '.(isset($error['code'])?$error['code']:'unknown').' '.(preg_match('/^CREATE TABLE ([A-Za-z0-9_]+)/',$sql,$m)?$m[1]:''));}return$r;}
function acr_rows($sql){global$control;$r=acr_sql($sql);try{return$control->sql_fetchrowset($r);}finally{$control->sql_freeresult($r);}}
function acr_literal($s){return'CONVERT(0x'.bin2hex($s).' USING utf8mb4)';}
function acr_files($name){global$root;return array($root.'/album_mod/upload/'.$name,$root.'/album_mod/upload/cache/'.$name,$root.'/album_mod/upload/med_cache/'.$name);}
function acr_upload($digit,$old=true,$published=false,$picture=7){global$source,$root,$knownFiles,$cases;
