	if($old){acr_sql('UPDATE fixture_album_file_jobs SET created_at='.(time()-8*86400)." WHERE operation_id='".$d['operation']."'");}$cases++;return array('descriptor'=>$d,'items'=>$items,'paths'=>acr_files($name),'bytes'=>$bytes);
}
function acr_cli($arguments,$expect=0){global$base,$cases;
	$runner=isset($GLOBALS['cliBase'])?$GLOBALS['cliBase']:$base;$command=escapeshellarg(PHP_BINARY).' ';if(DIRECTORY_SEPARATOR===chr(92)){$command.='-n -d '.escapeshellarg('extension_dir='.ini_get('extension_dir')).' -d extension=php_mysqli.dll -d extension=php_openssl.dll ';if(extension_loaded('mbstring')){$command.='-d extension=php_mbstring.dll ';}}$command.=escapeshellarg($runner.'/update/recover_album_files.php');foreach($arguments as$a){$command.=' '.escapeshellarg($a);}
	$p=proc_open($command,array(0=>array('pipe','r'),1=>array('pipe','w'),2=>array('pipe','w')),$pipes,null,null,array('bypass_shell'=>true));acr_check(is_resource($p),'Start actual recovery CLI');fclose($pipes[0]);$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$status=proc_close($p);acr_check($status===$expect,'Actual CLI exit status '.$status.' expected '.$expect.': '.$out.$err);$cases++;
	if($expect!==0){acr_check($out==='','Refusal prints no private content or partial success');return null;}$report=json_decode($out,true);acr_check(is_array($report)&&$err==='','Actual CLI emits one valid report');foreach(array('binding_hash','capability_hash','filename','Owned recovery image bytes')as$private){acr_check(strpos($out,$private)===false,'Report omits private filenames/content/capabilities');}return$report;
}
function acr_apply($extra=array(),$expect=0){return acr_cli(array_merge(array('--apply','--backup-confirmed'),$extra),$expect);}
