	for($i=0;$i<2;$i++){$report=acr_apply(array('--jobs=1','--items=1'));}acr_check(!$report['incomplete']&&$report['next_after']===$old['descriptor']['operation'],'Cursor advances only when cleanup finishes');foreach($old['paths']as$path){acr_check(!file_exists($path),'All abandoned upload scopes removed');}foreach(array($recent,$published)as$job){foreach($job['paths']as$path){acr_check(file_get_contents($path)===$job['bytes'],'Current/recent published bytes preserved');}}$cases++;
