	$changed=acr_upload('5');acr_check(file_put_contents($changed['paths'][0],'Keep changed original')===21,'Change own original');$report=acr_apply();acr_check(isset($report['jobs'][0]['outcomes']['changed'])&&file_get_contents($changed['paths'][0])==='Keep changed original','Changed file remains exact');$cases++;
	$malformed=acr_upload('6');acr_sql("UPDATE fixture_album_file_items SET file_sha256='invalid' WHERE operation_id='".$malformed['descriptor']['operation']."' AND item_index=0");acr_apply(array(),3);foreach($malformed['paths']as$path){acr_check(file_get_contents($path)===$malformed['bytes'],'Malformed journal cannot grant file deletion');}acr_sql('UPDATE fixture_album_file_items SET file_sha256='.acr_literal(hash('sha256',$malformed['bytes']))." WHERE operation_id='".$malformed['descriptor']['operation']."' AND item_index=0");acr_apply();$cases++;
	$next=acr_upload('7');$last=acr_upload('8');$report=acr_apply(array('--jobs=1','--items=3'));acr_check($report['selected']===1&&$report['more_available']&&$report['next_after']===$next['descriptor']['operation'],'Job budget selects one exact page and reports remaining work');$report=acr_apply(array('--jobs=1','--items=3','--after='.$report['next_after']));acr_check($report['next_after']===$last['descriptor']['operation']&&!$report['more_available'],'Next cursor resumes exact remaining page');$cases++;
	acr_sql("INSERT INTO fixture_album_cat(cat_id,cat_title,cat_desc,cat_order,cat_user_id) VALUES(1,'Own cleanup category','',1,0)");$deleted=acr_upload('9',true,true,9);$c=new AlbumFileCoordinator($source,'fixture_');try{$c->begin();$cleanup=new AlbumCleanupReceipt($c,'fixture_',$root);$jobs=$cleanup->prepare(7,0,1,array(9));$c->sql_query('DELETE FROM fixture_album WHERE pic_id=9');$c->commit();}finally{$c->release();}
	for($i=0;$i<3;$i++){$report=acr_apply(array('--items=1'));acr_check($report['attempted_items']<=1,'Delete file budget stays bounded');}foreach($deleted['paths']as$path){acr_check(!file_exists($path),'Committed picture deletion resumes all owned paths');}acr_check(acr_rows("SELECT operation_state FROM fixture_album_file_jobs WHERE operation_id='".$jobs[0]['operation']."'")[0]['operation_state']==='complete','Cleanup receipt remains terminal');$cases++;
