	foreach(array('update/recover_album_files.php','update/album_file_recovery.php','phpBB2/includes/php_compat.php','phpBB2/includes/functions_username.php','phpBB2/includes/functions_post_author.php','phpBB2/includes/functions_author_visibility.php','phpBB2/db/mysqli.php','phpBB2/album_mod/album_file_coordinator.php','phpBB2/album_mod/album_file_storage.php','phpBB2/album_mod/album_upload_receipt.php','phpBB2/album_mod/album_upload_recovery.php','phpBB2/album_mod/album_cleanup_receipt.php')as$file){$dest=$flat.'/'.preg_replace('#^phpBB2/#','',$file);acr_check(copy($project.'/'.$file,$dest),'Own flat fixture code');$copies[]=$dest;}acr_check(file_put_contents($flat.'/config.php',$config)===strlen($config),'Own flat configuration');$copies[]=$flat.'/config.php';$root=realpath($flat);$cliBase=$root;$flatUpload=acr_upload('a');$report=acr_cli(array());acr_check($report['selected']===1,'Flat preview reads its configured journal');acr_apply();foreach($flatUpload['paths']as$path){acr_check(!file_exists($path),'Flat layout cleans its own owned files');}$cases++;
